<?php declare(strict_types=1);namespace App\Controllers\Api;use App\Core\Request;use App\Core\Response;use App\Models\Release;use App\Services\UpdateService;final class UpdateController{public function latest(Request $b):Response{$o=$b->str('channel','stable')==='beta'?'beta':'stable';$i=$b->str('current')?:null;$c=UpdateService::latest($o,$i);if(!$c){return Response::error('no_release',404);}$u=Release::toApi($c);$u['update_available']=$i===null||version_compare($c['version'],$i,'>');$u['ok']=true;return Response::json($u)->withHeader('Cache-Control','public, max-age=300');}public function releases(Request $k):Response{$a=Release::castAll(Release::query()->where('is_active',1)->orderBy('published_at','DESC')->limit(50)->get());return Response::json(['ok'=>true,'releases'=>array_map([Release::class,'toApi'],$a)]);}public function publish(Request $i):Response{$I=$i->isJson()?$i->json():$i->body;try{$M=UpdateService::publishManifest($I,true);}catch(\App\Services\ConflictException $a){return Response::error('conflict',409,['message'=>$a->getMessage()]);}catch(\InvalidArgumentException $a){return Response::error('validation',422,['message'=>$a->getMessage(),'fields'=>['manifest'=>$a->getMessage()]]);}\App\Models\AuditLog::log('api.updates.publish',$M['version'],['channel'=>$M['channel'],'user'=>'editor']);$e=Release::toApi($M);return Response::json(['ok'=>true,'release'=>array_merge(['id'=>(int)$M['id']],$e)],201);}}